INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64347242', 64347242, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN SENIOR PROGRAMMER PENGEMBANGAN FRONTEND SISTEM INFORMASI KRISNA', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 664000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Memberikan rekomendasi teknis strategis kepada Direktorat Alokasi Anggaran Pembangunan Pusat dan Daerah Bappenas terkait arah pengembangan, modernisasi, dan penyempurnaan arsitektur front end Sistem Informasi KRISNA, baik untuk Pemerintah Pusat maupun Pemerintah Daerah. Merancang dan menetapkan desain arsitektur front end tingkat lanjut (advanced front end architecture) KRISNA dan teknologi pendukung yang menjamin skalabilitas, keamanan, dan keberlanjutan sistem. Berperan sebagai lead technical advisor dalam kolaborasi dengan Konsultan Senior System Analyst dan tim pengembangan lainnya, khususnya dalam penerjemahan kebutuhan bisnis perencanaan dan penganggaran menjadi solusi antarmuka pengguna yang kompleks dan terintegrasi. Menganalisis dan merancang pengembangan fitur strategis dan kompleks pada Sistem Informasi KRISNA, termasuk fitur lintas-sub sistem dan fitur yang mendukung sinkronisasi perencanaan dan penganggaran Pemerintah Pusat dan Pemerintah Daerah. Memastikan sistem berjalan dengan lancar tanpa kendala dan memperbaiki dengan cepat jika ada permasalahan sistem, serta memperbaiki rules aplikasi agar sistem berjalan dengan efisien dengan cara melakukan proses refactor secara berkala dan sesuai kebutuhan; Mengembangkan, mengimplementasikan, dan memelihara antarmuka pengguna Sistem Informasi KRISNA, baik terkait Pemerintah Pusat dan Pemerintah Daerah; Melakukan reviu code (code review) terhadap hasil kerja Konsultan lainnya untuk memastikan kesesuaian dengan standar penulisan kode (coding convention), efisiensi algoritma dan struktur komponen; Merancang konsep integrasi antarmuka pengguna (UI integration layer) KRISNA dengan sistem informasi lain di lingkungan Kementerian PPN/Bappenas maupun Kementerian/Lembaga lain, termasuk penanganan kompleksitas interoperabilitas dan konsistensi pengalaman pengguna. Menyusun laporan kegiatan yang telah dilaksanakan sesuai dengan jadwal yang telah ditentukan;', 'Diutamakan Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pendidikan minimal S1 di bidang Ilmu Komputer/Teknik Informatika/Sistem Informasi (dibuktikan dengan ijazah jenjang pendidikan); Memiliki pengalaman minimal 9 (sembilan) tahun sebagai Programmer (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS atau Pagu Anggaran (dibuktikan dengan surat referensi/kontrak kerja); Bersedia untuk bekerja di luar jam kerja (lembur) dan dalam jadwal ketat; Memiliki kemampuan yang baik dalam (dibuktikan dengan surat referensi/kontrak kerja): analisa permasalahan; problem solving; desain sistem berskala besar dan kompleks; mengatur jadwal dan tugas-tugas; Berpengalaman dalam hal (dibuktikan dengan surat referensi/kontrak kerja): membangun sistem berskala besar; membangun sistem informasi web based perencanaan dan penganggaran, khususnya pemerintah pusat; membangun Sistem Informasi perencanaan dan penganggaran pemerintah pusat dalam skala nasional; membangun Custom Business Intelligence; membangun sistem monitoring pelaporan instansi pemerintah bekerjasama dengan Pemerintah Pusat maupun Pemerintah Daerah; bekerja dengan framework MVC; bekerja dengan metodologi Agile; bekerja dengan API services; bekerja dengan Object Oriented Programming; berkolaborasi dengan IT Developer, Business Intelligence dan Data Team Members. Memiliki penguasaan terhadap hal-hal sebagai berikut (dibuktikan dengan Portofolio (Laporan pekerjaan atau screenshot aplikasi) dan/atau sertifikasi keahlian (SKA/Sertifikat Kompetensi)):', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1525334);
