INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64411495', 64411495, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI PERENCANAAN PEMBANGUNAN', 'Penyediaan Jasa Konsultansi Perorangan Analis Data Terampil 5', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 70950000, 'January 2026', 'APBD', 1, 1, '1 Paket', '"1. Menganalisa, mengolah, dan menyajikan data statistik; 2. Menganalisa, mengolah, dan menyajikan data perencanaan dan pembangunan; 3. Menganalisa dan membuat laporan terkait perkembangan Satu Data Indonesia secara berkala Bidang Urusan Perekonomian dan Kesejahteraan Rakyat; 4. Membuat rekapitulasi hasil pelaksanaan monitoring dan pelaporan hasil pelaksanaan Rencana Aksi Satu Data Indonesia Tingkat Provinsi Bidang Urusan Perekonomian dan Kesejahteraan Rakyat; 5. memvalidasi hasil pengumpulan, verifikasi dan unggahan data Badan Perencanaan Pembangunan Daerah yang masuk dalam daftar data provinsi ke dalam Portal Satu Data Jakarta sesuai jadwal pemutakhiran dan jadwal rilis; 6. Melakukan koordinasi dengan pembina data, walidata, walidata pendukung, produsen data dan instansi terkait lainnya dalam rangka penyelenggaraan Satu Data Indonesia tingkat provinsi Bidang Urusan Perekonomian dan Kesejahteraan Rakyat; 7. Mendukung pelaksanaan tugas sekretariat Satu Data Indonesia tingkat provinsi Bidang Urusan Perekonomian dan Kesejahteraan Rakyat; 8. Mendukung pelaksanaan Forum Satu Data Indonesia tingkat provinsi; 9. Membantu pelaksanaan kegiatan Pusdatinenbang dalam pengelolaan data lainnya; 10. Membuat laporan hasil pekerjaan setiap akhir bulan."', 'Tenaga Ahli Tidak Ber SKA / SKK , S1 Pengalaman Minimal 5 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1529168);
